            let distance = hull
                .player_beam_distance(pose, origin, ray, 1000.0)?
                .ok_or("native surface")?;
            let contact = scene
                .nearest(&world, origin, ray, 1000.0, None, true)?
                .ok_or("EMP contact")?;
            assert_eq!((contact.0, contact.2), (victim, distance));
        }
