#[test]
fn medusa_exchange_preserves_real_emp_target_and_peregrine_self_splash() {
    let mut world = World::new_commander(12001).unwrap();
    secret(&mut world);
    let (mut world, target) = defender(world);
    start_charge(&mut world, target);
    hold(&mut world, target, 600);
    let profile = world
        .owned_emp()
        .unwrap()
        .grades
        .profile(super::State::energy_stage(&world).unwrap())
        .unwrap();
    let pulse = world.emp.pulses[0].clone();
    assert!(
        pulse
            .contacts
            .iter()
            .any(|contact| contact.victim == scene::Victim::Player)
    );
    world
        .request_emp_trigger(false, world.snapshot().tick)
        .unwrap();
    crate::flight::missiles::tests::issue_medusa_at_renas(&mut world);
    let loaded = cold(&world);
    assert_eq!(loaded.emp.pulses[0], pulse);
    let contacts = pulse.release.contacts(&loaded, profile, target).unwrap();
    assert_eq!(contacts, pulse.contacts);
}

#[test]
fn medusa_exchange_retains_peregrine_missile_impact_and_guides_on_live_npc_mesh() {
    let mut world = impacted();
    let hit = world.traffic.missile_hits()[0];
    crate::flight::missiles::tests::issue_medusa_at_renas(&mut world);
    world = cold(&world);
    assert_eq!(world.traffic.missile_hits()[0], hit);
    // Start a separate Medusa flight with fresh local traffic for the live guidance query.
    let mut world = World::new_commander(12005).unwrap();
    let issue = world
        .review_xyzzy(crate::XyzzyAction::ActivateMedusa, 0)
        .unwrap();
    world.prepare_xyzzy(issue, 0).unwrap().commit();
    launch(&mut world);
    for _ in 0..700 {
        world
            .step(crate::FlightInput {
                throttle: 1.0,
                ..Default::default()
            })
            .unwrap();
    }
    let npc = trader(&world);
    let origin =
        crate::flight::flight_pose(world.snapshot().position, world.snapshot().orientation)
            .unwrap()
            .position;
    let geometry = world.station_data.as_ref().unwrap();
    let correct = geometry
        .npc_geometry()
        .player_missile_aimpoint(npc.pose, origin)
        .unwrap();
    assert_ne!(
        geometry.player_missile_aimpoint(npc.pose, origin).unwrap(),
        correct
    );
    assert_eq!(
        world
            .resolve_missile_guidance(
                MissileTarget::Npc(npc.id),
                origin,
                &world.traffic,
                world.practice
            )
            .unwrap(),
        Some(correct)
    );
    cold(&world);
}

